import gurobipy as gp
from gurobipy import GRB
platforms = []
capacity = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        rid = rec['values']['resource_id']
        platforms.append(rid)
        capacity[rid] = int(rec['values']['resource_capacity'])
genres = []
value = {}
requirement = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        name = rec['values']['item_name']
        genres.append(name)
        value[name] = int(rec['values']['item_value'])
        requirement[name] = int(rec['values']['resource_requirement'])
if len(platforms) == 0 or len(genres) == 0:
    raise ValueError('Missing platforms or genres in LEGACY_RECORDS')
for rid in platforms:
    if rid not in capacity:
        raise ValueError(f'Missing capacity for platform {rid}')
for name in genres:
    if name not in value or name not in requirement:
        raise ValueError(f'Missing value or requirement for genre {name}')
m = gp.Model('VideoGameStore_Listing')
x_vars = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[j] * x_vars[i, j] for i in platforms for j in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((requirement[j] * x_vars[i, j] for j in genres)) <= capacity[i] for i in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')